bad=[]
for p in pathlib.Path("docs/explanation").glob("*.md"):
    t=re.sub(r"^(```|~~~).*?^(```|~~~)","",p.read_text(),flags=re.S|re.M)
    for tok in re.findall(r"`([^`\s]+\.[A-Za-z0-9]+)`",t):
        if tok in ALLOW or tok.startswith(("/","~")) or pathlib.Path(tok).exists(): continue
        if any(f.endswith("/"+tok.lstrip("./")) for f in tr): bad.append(f"{p}: {tok}")
print("\n".join(bad))
sys.exit(1 if bad else 0)'
